const articles=articleData.map((a,i)=>({id:i+1,title:a[0],category:a[1],description:a[2],p1:a[3],p2:a[4],p3:a[5],takeaway:a[6],image:imageUrls[i],date:dates[i],minutes:readingTimes[i]}));
let state={language:"en",category:"all",query:"",sort:"relevant",time:"all",activeArticle:null};
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const t=()=>I18N[state.language];
function articleText(a){const tr=translations[state.language]?.[a.id-1];return {title:tr?.[0]||a.title,description:tr?.[1]||a.description};}
function categoryName(key){if(key==="all")return t().categoryAll;return t().categories[categoryIndex[key]]||key;}
function formatDate(date){return new Intl.DateTimeFormat(state.language==="en"?"en-GB":state.language==="am"?"am-ET":state.language==="om"?"om-ET":state.language==="so"?"so-SO":"ti-ET",{day:"numeric",month:"short",year:"numeric"}).format(new Date(date+"T12:00:00"));}
function translatedBody(){return localizedBodies[state.language]||localizedBodies.en;}
function applyTranslations(){
 document.documentElement.lang=state.language;
 document.querySelectorAll("[data-i18n]").forEach(el=>{const key=el.dataset.i18n;if(t()[key])el.textContent=t()[key];});
 document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{const key=el.dataset.i18nPlaceholder;if(t()[key])el.placeholder=t()[key];});
 $("#sortSelect").options[0].text=t().mostRelevant;$("#sortSelect").options[1].text=t().latest;$("#sortSelect").options[2].text=t().oldest;
 $("#timeSelect").options[0].text=t().all;$("#timeSelect").options[1].text=t().under5;$("#timeSelect").options[2].text=t().fiveToTen;$("#timeSelect").options[3].text=t().above10;
 renderCategories();renderFeatured();renderArticles();
 if(state.activeArticle)renderReader(state.activeArticle);
}
function renderCategories(){
 const el=$("#categoryFilters");
 el.innerHTML=`<button class="category-btn ${state.category==="all"?"active":""}" data-category="all">${escapeHTML(t().categoryAll)}</button>`+
 categoryKeys.map(k=>`<button class="category-btn ${state.category===k?"active":""}" data-category="${escapeHTML(k)}">${escapeHTML(categoryName(k))}</button>`).join("");
 el.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{state.category=b.dataset.category;renderCategories();renderArticles();}));
}
function cardHTML(a,compact=false){
 const tx=articleText(a);
 return `<article class="${compact?"related-card":"article-card"}">${compact?`<img src="${a.image}" alt="${escapeHTML(tx.title)}" loading="lazy"><div><h3>${escapeHTML(tx.title)}</h3><button data-read="${a.id}">${escapeHTML(t().readMore)} →</button></div>`:`<div class="card-image-wrap"><img class="card-image" src="${a.image}" alt="${escapeHTML(tx.title)}" loading="lazy"></div><div class="card-body"><span class="category-label">${escapeHTML(categoryName(a.category))}</span><h3>${escapeHTML(tx.title)}</h3><p>${escapeHTML(tx.description)}</p><div class="card-bottom"><span class="card-date">${formatDate(a.date)} · ${a.minutes} ${escapeHTML(t().minRead)}</span><button class="read-link" data-read="${a.id}">${escapeHTML(t().readMore)} →</button></div></div>`}</article>`;
}
function renderFeatured(){
 const a=articles[0],tx=articleText(a);
 $("#featuredCard").innerHTML=`<img class="featured-image" src="${a.image}" alt="${escapeHTML(tx.title)}"><div class="featured-copy"><span class="feature-label">${escapeHTML(t().editorChoice)}</span><span class="category-label">${escapeHTML(categoryName(a.category))}</span><h3>${escapeHTML(tx.title)}</h3><p>${escapeHTML(tx.description)}</p><div class="meta-row"><span>${formatDate(a.date)}</span><span>${a.minutes} ${escapeHTML(t().minRead)}</span><span>${escapeHTML(t().author)}</span></div><button class="primary-button" data-read="${a.id}">${escapeHTML(t().readArticle)} <span>→</span></button></div>`;
}
function filteredArticles(){
 let list=articles.filter(a=>(state.category==="all"||a.category===state.category));
 const q=state.query.trim().toLocaleLowerCase();
 if(q)list=list.filter(a=>{const tx=articleText(a);return [tx.title,tx.description,a.title,a.description,a.category].join(" ").toLocaleLowerCase().includes(q);});
 if(state.time==="short")list=list.filter(a=>a.minutes<5);
 if(state.time==="medium")list=list.filter(a=>a.minutes>=5&&a.minutes<=10);
 if(state.time==="long")list=list.filter(a=>a.minutes>10);
 if(state.sort==="latest")list.sort((a,b)=>b.date.localeCompare(a.date));
 if(state.sort==="oldest")list.sort((a,b)=>a.date.localeCompare(b.date));
 return list;
}
function renderArticles(){
 const list=filteredArticles();
 $("#articleGrid").innerHTML=list.map(a=>cardHTML(a)).join("");
 $("#articleCount").textContent=articles.length;
 $("#resultsText").textContent=`${t().showing} ${list.length} ${t().of} ${articles.length} ${t().articlesWord}`;
 $("#emptyState").hidden=list.length!==0;$("#articleGrid").hidden=list.length===0;
 $("#articleGrid").querySelectorAll("[data-read]").forEach(b=>b.addEventListener("click",()=>openArticle(Number(b.dataset.read))));
}
function renderReader(id){
 const a=articles.find(x=>x.id===id);if(!a)return;
 const tx=articleText(a),body=translatedBody();
 const heading2=state.language==="en"?"Why it matters":body.section1;
 const p1=state.language==="en"?a.p1:body.intro+" "+a.p1;
 const p2=state.language==="en"?a.p2:body.intro+" "+a.p2;
 const p3=state.language==="en"?a.p3:body.intro+" "+a.p3;
 $("#articleReader").innerHTML=`<img class="reader-cover" src="${a.image}" alt="${escapeHTML(tx.title)}"><div class="reader-content"><span class="category-label">${escapeHTML(categoryName(a.category))}</span><h1>${escapeHTML(tx.title)}</h1><div class="reader-meta"><span>${escapeHTML(t().published)}: ${formatDate(a.date)}</span><span>${a.minutes} ${escapeHTML(t().minRead)}</span><span>${escapeHTML(t().author)}</span></div><p class="reader-intro">${escapeHTML(tx.description)}</p><h2>${escapeHTML(t().overview)}</h2><p>${escapeHTML(p1)}</p><h2>${escapeHTML(heading2)}</h2><p>${escapeHTML(p2)}</p><h2>${escapeHTML(body.section2)}</h2><p>${escapeHTML(p3)}</p><h2>${escapeHTML(body.section3)}</h2><ul><li>${escapeHTML(state.language==="en"?"Observe conditions regularly and keep clear records.":body.intro)}</li><li>${escapeHTML(state.language==="en"?"Use trusted local guidance and adapt decisions to your farm.":body.intro)}</li><li>${escapeHTML(state.language==="en"?"Review outcomes after harvest and improve the next season's plan.":body.intro)}</li></ul><div class="info-note"><strong>${escapeHTML(t().keyTakeaway)}:</strong> ${escapeHTML(a.takeaway)}<br><br>${escapeHTML(body.note)}</div></div>`;
 const related=articles.filter(x=>x.id!==id&&x.category===a.category).concat(articles.filter(x=>x.id!==id&&x.category!==a.category)).slice(0,3);
 $("#relatedGrid").innerHTML=related.map(x=>cardHTML(x,true)).join("");
 $("#relatedGrid").querySelectorAll("[data-read]").forEach(b=>b.addEventListener("click",()=>openArticle(Number(b.dataset.read))));
}
function openArticle(id){state.activeArticle=id;$("#listingView").hidden=true;$("#readerView").hidden=false;renderReader(id);window.scrollTo({top:0,behavior:"smooth"});}
function backToListing(){state.activeArticle=null;$("#readerView").hidden=true;$("#listingView").hidden=false;window.scrollTo({top:$("#articles").offsetTop-80,behavior:"smooth"});}
$("#searchForm").addEventListener("submit",e=>{e.preventDefault();state.query=$("#searchInput").value;renderArticles();$("#articles").scrollIntoView({behavior:"smooth"});});
$("#searchInput").addEventListener("input",e=>{state.query=e.target.value;renderArticles();});
$("#sortSelect").addEventListener("change",e=>{state.sort=e.target.value;renderArticles();});
$("#timeSelect").addEventListener("change",e=>{state.time=e.target.value;renderArticles();});
function clearFilters(){state.category="all";state.query="";state.sort="relevant";state.time="all";$("#searchInput").value="";$("#sortSelect").value="relevant";$("#timeSelect").value="all";renderCategories();renderArticles();}
$("#clearFilters").addEventListener("click",clearFilters);$("#emptyClear").addEventListener("click",clearFilters);
$("#languageSelect").addEventListener("change",e=>{state.language=e.target.value;applyTranslations();});
$("#backButton").addEventListener("click",backToListing);
$("#menuToggle").addEventListener("click",()=>{const open=$("#mainNav").classList.toggle("open");$("#menuToggle").setAttribute("aria-expanded",String(open));});
document.querySelectorAll("[data-read]").forEach(b=>b.addEventListener("click",()=>openArticle(Number(b.dataset.read))));
$("#year").textContent=new Date().getFullYear();
applyTranslations();
